SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAMU HAKKI (BEYTÜLMAL) VE ORTAK YAŞAM SORUMLULUĞU</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Kamu Hakkı İhlalleri (Büyük Günah)</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Okul, park, toplu taşıma ve hastane malına zarar</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Vergi kaçırmak ve kamu kaynaklarını israf etmek</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Görevlendirmelerde torpil (iltimas) ve rüşvet</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• Trafik kurallarını çiğneyip can güvenliğini bozmak</text>\n  <text x="55" y="208" font-size="11.5" font-weight="bold" fill="#991b1b">• Milyonlarca vatandaşın kul hakkına girmektir!</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Emanet ve Liyakat Bilinci</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• "Allah size emanetleri ehli olanlara (liyakat</text>\n  <text x="390" y="126" font-size="11" fill="#475569">sahiplerine) vermenizi emreder." (Nisâ, 58)</text>\n  <text x="380" y="154" font-size="11.5" fill="#334155">• Makam ve görevler topluma hizmet emanetidir.</text>\n  <text x="380" y="180" font-size="11.5" fill="#334155">• Ahde Vefa: Verilen söz ve anlaşmaları tutmaktır.</text>\n  <text x="380" y="208" font-size="11.5" font-weight="bold" fill="#1e40af">• Mümin, elinden ve dilinden emin olunan kişidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA ÇEVRE AHLAKI VE EKOLOJİK DENGE (MÎZÂN)</text>\n  <rect x="30" y="55" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Doğal Dengeyi Koruma</text>\n  <text x="130" y="110" text-anchor="middle" font-size="11" fill="#334155">"İnsanların kendi elleriyle</text>\n  <text x="130" y="128" text-anchor="middle" font-size="11" fill="#334155">yaptıkları yüzünden karada</text>\n  <text x="130" y="146" text-anchor="middle" font-size="11" fill="#334155">ve denizde düzen bozuldu."</text>\n  <text x="130" y="168" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">(Rûm Suresi, 41. ayet)</text>\n  <text x="130" y="202" text-anchor="middle" font-size="11" fill="#475569">Doğa insana emanettir.</text>\n  <rect x="250" y="55" width="200" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Su ve Kaynak Tasarrufu</text>\n  <text x="350" y="110" text-anchor="middle" font-size="11" fill="#334155">"Akan bir nehrin kenarında</text>\n  <text x="350" y="128" text-anchor="middle" font-size="11" fill="#334155">abdest alsanız bile suyu</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11" fill="#334155">israf etmeyiniz."</text>\n  <text x="350" y="168" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">(Hadis-i Şerif)</text>\n  <text x="350" y="202" text-anchor="middle" font-size="11" fill="#475569">İsraf haram kılınmıştır.</text>\n  <rect x="470" y="55" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ağaçlandırma ve Merhamet</text>\n  <text x="570" y="110" text-anchor="middle" font-size="11" fill="#334155">"Kıyametin kopacağını</text>\n  <text x="570" y="128" text-anchor="middle" font-size="11" fill="#334155">bilseniz bile elinizdeki</text>\n  <text x="570" y="146" text-anchor="middle" font-size="11" fill="#334155">fidanı dikiniz."</text>\n  <text x="570" y="168" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">(Hadis-i Şerif)</text>\n  <text x="570" y="202" text-anchor="middle" font-size="11" fill="#475569">Sadaka-i câriye sevabıdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TOPLUMSAL DAYANIŞMA VE KOMŞULUK HUKUKU</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Komşuluk ve Görgü Kuralları</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Komşunun sevincini ve üzüntüsünü paylaşmak</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Gürültü ve çöple komşuyu rahatsız etmemek</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Selamlaşmayı yaygınlaştırmak (İfşâü\'s-selâm)</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• Yoldaki eziyet verici engelleri kaldırmak</text>\n  <text x="55" y="208" font-size="11" font-weight="bold" fill="#9d174d">(İmâtetu\'l-ezâ: İmanın şubelerinden sayılmıştır)</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Vakıf Kültürü ve Sadaka-i Câriye</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Kişi vefat etse de sevabı kesilmeyen hayırlara</text>\n  <text x="390" y="126" font-size="11.5" font-weight="bold" fill="#166534">Sadaka-i Câriye denir.</text>\n  <text x="380" y="154" font-size="11.5" fill="#334155">• Okul, çeşme, şifahane, kütüphane, köprü ve</text>\n  <text x="390" y="172" font-size="11" fill="#475569">kuş evleri vakıf medeniyetimizin eserleridir.</text>\n  <text x="380" y="204" font-size="11.5" font-weight="bold" fill="#15803d">• İyilik ve takvada yardımlaşma emredilmiştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
